"""Write docs/reference/cli.md from the click command tree: uv run python tools/gen_cli_doc.py"""

import sys
from pathlib import Path

import click

from kb.cli import main


def walk(cmd, path):
    yield path, cmd
    if isinstance(cmd, click.Group):
        for name in cmd.list_commands(None):
            yield from walk(cmd.commands[name], path + [name])


def render() -> str:
    out = ["# Command reference", "",
           "Generated by `tools/gen_cli_doc.py` from `kb --help`; a test keeps it in sync.", ""]
    for path, cmd in walk(main, ["kb"]):
        ctx = click.Context(cmd, info_name=" ".join(path), terminal_width=100, max_content_width=100,
                            help_option_names=["-h", "--help"])
        out += [f"## {' '.join(path)}", "", "```", cmd.get_help(ctx).rstrip(), "```", ""]
    return "\n".join(out).rstrip() + "\n"


if __name__ == "__main__":
    target = Path(__file__).parent.parent / "docs" / "reference" / "cli.md"
    target.write_text(render())
    print(target, file=sys.stderr)
